function onFilterChange(next) {
  gridRef.current?.style.setProperty('--row-density', next.density);
  startTransition(() => setFilter(next)); // yieldable transition lane
  requestAnimationFrame(() => {
    const heights = rowsRef.current.map((el) => el.getBoundingClientRect().height);
    rowsRef.current.forEach((el, i) => (el.style.minHeight = `${heights[i] + 4}px`));
  });
